// Command docsdriftlint guards the hand-written parts of the documentation
// templates against schema drift.
//
// docs/ is generated by terraform-plugin-docs (tfplugindocs) from templates/:
// every page embeds {{ .SchemaMarkdown }}, so the argument and attribute
// lists come from the schema and cannot drift. CI regenerates docs/ and fails
// on a diff. What generation cannot keep in sync is the prose around the
// schema, so this linter checks the templates:
//
//   - every registered provider, resource, data source, ephemeral resource,
//     list resource and action has a template; without one tfplugindocs
//     silently writes a default page that has no examples and no prose;
//   - every template embeds .SchemaMarkdown, so its schema part is generated;
//   - every template belongs to a registered type, so a renamed or removed
//     type does not leave its page behind;
//   - a field named in a hand-written table (first column of a table whose
//     header is "Name", "Attribute", "Argument" or "Field") or in a
//     "Notes on Arguments and Attributes" bullet exists in the schema, at any
//     depth (object type members included), so renamed fields do not linger.
//     Such tables are the ones the schema cannot express: the fields of
//     object-typed attributes and the results of list resources. "id" is
//     always accepted, as list results carry it as their identity. A name
//     with the "portainer_" prefix (the type tables of index.md) has to be a
//     registered type instead.
//
// The schemas are read as Terraform receives them, from the provider server
// (internal.NewProviderServer, GetProviderSchema).
//
// Usage: docsdriftlint [module-root]   (defaults to ".")
package main

import (
	"context"
	"flag"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"github.com/portainer/terraform-provider-portainer/internal"
)

type violation struct {
	tfName string
	doc    string
	msg    string
}

// kindDirs maps a LintSchema kind to its templates/ (and docs/) subdirectory.
var kindDirs = map[string]string{
	"resource":           "resources",
	"data source":        "data-sources",
	"ephemeral resource": "ephemeral-resources",
	"list resource":      "list-resources",
	"action":             "actions",
}

func main() {
	flag.Parse()
	root := "."
	if args := flag.Args(); len(args) > 0 {
		root = args[0]
	}

	schemas, err := internal.LintSchemas(context.Background())
	if err != nil {
		fmt.Fprintf(os.Stderr, "docsdriftlint: %v\n", err)
		os.Exit(2)
	}

	violations, checked, err := check(root, schemas)
	if err != nil {
		fmt.Fprintf(os.Stderr, "docsdriftlint: %v\n", err)
		os.Exit(2)
	}
	if len(violations) == 0 {
		fmt.Printf("docsdriftlint: OK — every schema has a template that embeds its generated schema, and every field the templates name exists (%d templates checked).\n", checked)
		return
	}

	sort.Slice(violations, func(i, j int) bool {
		if violations[i].tfName != violations[j].tfName {
			return violations[i].tfName < violations[j].tfName
		}
		return violations[i].msg < violations[j].msg
	})
	for _, v := range violations {
		fmt.Printf("%s (%s): %s\n", v.tfName, v.doc, v.msg)
	}
	fmt.Fprintf(os.Stderr, "\ndocsdriftlint: %d template issue(s). Fix the template(s) under templates/, then run `make docs-generate`.\n", len(violations))
	os.Exit(1)
}

// templatePath returns the template of a schema, relative to root.
func templatePath(s internal.LintSchema) (string, bool) {
	if s.Kind == "provider" {
		return filepath.Join("templates", "index.md.tmpl"), true
	}
	dir, ok := kindDirs[s.Kind]
	if !ok {
		return "", false
	}
	return filepath.Join("templates", dir, strings.TrimPrefix(s.TypeName, "portainer_")+".md.tmpl"), true
}

// check compares the templates under root/templates with the schemas. It
// returns the violations and how many templates were checked.
func check(root string, schemas []internal.LintSchema) (violations []violation, checked int, err error) {
	expected := map[string]bool{}
	types := map[string]bool{}
	for _, s := range schemas {
		types[s.TypeName] = true
	}
	for _, s := range schemas {
		rel, ok := templatePath(s)
		if !ok {
			continue
		}
		expected[filepath.ToSlash(rel)] = true

		content, readErr := os.ReadFile(filepath.Join(root, rel))
		if readErr != nil {
			violations = append(violations, violation{s.TypeName, rel, "template not found"})
			continue
		}
		checked++
		text := string(content)
		if !strings.Contains(text, ".SchemaMarkdown") {
			violations = append(violations, violation{s.TypeName, rel, "template does not embed {{ .SchemaMarkdown }}"})
		}

		known := map[string]bool{"id": true}
		for _, f := range s.Fields() {
			known[f.Name] = true
			known[f.Path] = true
		}
		for _, f := range namedFields(text) {
			if strings.HasPrefix(f, "portainer_") {
				if !types[f] {
					violations = append(violations, violation{
						s.TypeName, rel,
						fmt.Sprintf("documented type %q is not registered", f),
					})
				}
				continue
			}
			if !known[f] && !known[lastSegment(f)] {
				violations = append(violations, violation{
					s.TypeName, rel,
					fmt.Sprintf("documented field %q is not in the schema", f),
				})
			}
		}
	}

	// Templates of types the provider does not register.
	for _, dir := range kindDirs {
		base := filepath.Join(root, "templates", dir)
		walkErr := filepath.WalkDir(base, func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				if os.IsNotExist(err) {
					return nil
				}
				return err
			}
			if d.IsDir() || !strings.HasSuffix(path, ".md.tmpl") {
				return nil
			}
			rel, relErr := filepath.Rel(root, path)
			if relErr != nil {
				return relErr
			}
			if !expected[filepath.ToSlash(rel)] {
				name := "portainer_" + strings.TrimSuffix(d.Name(), ".md.tmpl")
				violations = append(violations, violation{name, rel, "template has no registered " + strings.TrimSuffix(dir, "s")})
			}
			return nil
		})
		if walkErr != nil {
			return nil, 0, walkErr
		}
	}
	return violations, checked, nil
}

func lastSegment(path string) string {
	if i := strings.LastIndex(path, "."); i >= 0 {
		return path[i+1:]
	}
	return path
}

var (
	tableHeader = regexp.MustCompile(`^\|\s*\**(Name|Attribute|Argument|Field)\**\s*\|`)
	tableField  = regexp.MustCompile("^\\|\\s*`([a-z][a-z0-9_.]*)`\\s*\\|")
	notesHead   = regexp.MustCompile(`^#{2,6}\s+Notes on Arguments and Attributes\s*$`)
	noteField   = regexp.MustCompile("^-\\s+`([a-z][a-z0-9_.]*)`:")
	anyHeading  = regexp.MustCompile(`^#{1,6}\s`)
)

// namedFields returns the field names a template lists in the first column of
// its field tables and in its "Notes on Arguments and Attributes" bullets.
// Fenced code blocks are skipped.
func namedFields(text string) []string {
	var names []string
	inTable, inNotes, inFence := false, false, false
	for _, line := range strings.Split(text, "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "```") {
			inFence = !inFence
			continue
		}
		if inFence {
			continue
		}
		switch {
		case anyHeading.MatchString(line):
			inNotes = notesHead.MatchString(line)
			inTable = false
			continue
		case tableHeader.MatchString(line):
			inTable = true
			continue
		case !strings.HasPrefix(line, "|"):
			inTable = false
		}
		if m := tableField.FindStringSubmatch(line); inTable && m != nil {
			names = append(names, m[1])
		}
		if m := noteField.FindStringSubmatch(line); inNotes && m != nil {
			names = append(names, m[1])
		}
	}
	return names
}
